'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=['person','chamber','party','state','owner','ticker','company','type','asset','traded','filed','amount','source','notes'];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let imported=read('cl-imports',[]);if(!Array.isArray(imported))imported=[];
imported=imported.filter(r=>{try{validate(r);return true}catch{return false}}).map(r=>({...r,quality:'User-provided'}));
const savedFollows=read('cl-follows',[]); let follows=new Set((Array.isArray(savedFollows)?savedFollows:[]).filter(x=>typeof x==='string'));
let data=[...SEED,...imported],view='trades',scope='all',page=1;
const pageSize=20;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{notify('Browser storage is unavailable. Changes last only for this session.');return false}}
const lag=r=>Math.round((Date.parse(r.filed)-Date.parse(r.traded))/86400000);
const date=s=>new Date(s+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const initials=s=>s.split(' ').map(x=>x[0]).slice(0,2).join('');
function filtered(){clusters();const q=$('#search').value.trim().toLowerCase();return data.filter(r=>(!q||[r.person,r.company,r.ticker,r.owner].some(x=>x.toLowerCase().includes(q)))&&(!$('#chamber').value||r.chamber===$('#chamber').value)&&(!$('#type').value||($('#type').value==='Buys'?r.type==='Purchase'||r.type==='Exercise':r.type===$('#type').value))&&(scope!=='following'||follows.has(r.person))&&(scope!=='clusters'||clusterByRow.has(r.id))).sort((a,b)=>$('#sort').value==='upside'?(priceReturn(b)?.pct??-Infinity)-(priceReturn(a)?.pct??-Infinity)||b.traded.localeCompare(a.traded):b.traded.localeCompare(a.traded)||b.filed.localeCompare(a.filed));}
function renderStats(){const delays=data.map(lag).sort((a,b)=>a-b),mid=Math.floor(delays.length/2),median=delays.length%2?delays[mid]:(delays[mid-1]+delays[mid])/2;const values=[['trades',data.length],['politicians',new Set(data.map(r=>r.person)).size],['assets',new Set(data.map(r=>r.ticker)).size],['median delay',median+'d']];$('#stats').innerHTML=values.map(a=>`<span class="stat"><strong>${a[1]}</strong> ${a[0]}</span>`).join('');const counts={};data.filter(r=>r.type!=='Sale').forEach(r=>counts[r.ticker]=(counts[r.ticker]||0)+1);const ranked=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,4),max=ranked[0]?.[1]||1;$('#activity').innerHTML=ranked.map(([t,n])=>`<div class="bar-row"><span>${esc(t)}</span><div class="bar-track"><i style="width:${n/max*100}%"></i></div><b>${n}</b></div>`).join('');}
function renderRows(){renderClusters();const rows=filtered();page=Math.max(1,Math.min(page,Math.ceil(rows.length/pageSize)||1));const start=(page-1)*pageSize;$('#rows').innerHTML=rows.slice(start,start+pageSize).map(r=>`<tr><td class="who"><span class="person-name">${esc(r.person)}</span><small>${esc(r.owner)} · ${esc(r.party)}·${esc(r.state)}</small></td><td class="what"><span class="ticker" title="${esc(r.company)}">${esc(r.ticker)}</span>${clusterBadge(r)}<small>${esc(r.asset)} · ${esc(r.type)}</small></td><td class="when">${date(r.traded)}</td><td class="amount">${esc(r.amount)}</td>${priceCells(r)}<td class="filed">${date(r.filed)}<small>${lag(r)}d delay · ${r.quality==='Official filing'?'Official':r.quality==='Secondary source'?'Secondary':'Imported'}</small></td><td class="open-detail"><button class="row-details" data-detail="${esc(r.id)}" aria-label="View ${esc(r.person)} ${esc(r.ticker)} details">↗</button></td></tr>`).join('')||(scope==='clusters'?'<tr><td colspan="9"><div class="empty"><h2>No shared buys match</h2><p>Requires 2+ distinct politician households buying the same stock within the chosen window.</p><button class="secondary" data-scope="all">All trades</button></div></td></tr>':'<tr><td colspan="9"><div class="empty"><h2>No matching disclosures</h2><p>Try another search or follow a politician to build your watchlist.</p><button class="secondary" data-view="politicians">Browse politicians</button></div></td></tr>');$('#resultCount').textContent=rows.length?`${start+1}–${Math.min(start+pageSize,rows.length)} of ${rows.length} transactions`:'0 transactions';$('#pageCount').textContent=`${page} / ${Math.ceil(rows.length/pageSize)||1}`;$('#prev').disabled=page===1;$('#next').disabled=page*pageSize>=rows.length;}
function card(person){const records=data.filter(r=>r.person===person),r=records[0],latest=records.map(x=>x.filed).sort().at(-1);return `<article class="person-card"><span class="avatar">${esc(initials(person))}</span><h2>${esc(person)}</h2><p>${esc(r.chamber)} · ${esc(r.party)} · ${esc(r.state)}</p><div class="mini-stat"><span><b>${records.length}</b> selected trades</span>${PERFORMANCE[person]!==undefined?`<a class="performance" href="${PERFORMANCE_SOURCE}" target="_blank" rel="noopener" title="Unusual Whales estimate, reported by Benzinga; not audited or copy-trading returns">+${PERFORMANCE[person]}% · 2025 est. ↗</a>`:''}</div><p class="muted">Latest included filing · <b>${date(latest)}</b></p><button class="${follows.has(person)?'secondary':'primary'}" data-follow="${esc(person)}">${follows.has(person)?'★ Following · Unfollow':'☆ Follow'}</button><button class="text-button" data-person="${esc(person)}">View disclosures →</button></article>`}
function renderPeople(){const people=[...new Set(data.map(r=>r.person))].sort((a,b)=>a==='Donald Trump'?-1:b==='Donald Trump'?1:(PERFORMANCE[b]||0)-(PERFORMANCE[a]||0));$('#people').innerHTML=people.map(card).join('');const watched=people.filter(x=>follows.has(x));$('#watched').innerHTML=watched.length?watched.map(card).join(''):'<div class="empty panel"><h2>No saved politicians</h2><p>Follow a politician to keep their disclosures together.</p><button class="primary" data-view="politicians">Browse politicians</button></div>';$('#watchCount').textContent=follows.size;$('#followingCount').textContent=follows.size;}
function render(){renderStats();renderRows();renderPeople()}
function changeView(next){if(!['trades','politicians','watchlist','sources'].includes(next))return;view=next;['trades','politicians','watchlist','sources'].forEach(v=>$('#'+v+'View').hidden=v!==view);$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#stats').hidden=view==='sources';}
function follow(person){if(follows.has(person))follows.delete(person);else follows.add(person);persist('cl-follows',[...follows]);renderPeople();renderRows();notify(follows.has(person)?'Following '+person:'Removed '+person+' from your watchlist')}
function details(id){const r=data.find(x=>x.id===id);if(!r)return;$('#detailContent').innerHTML=`<div class="eyebrow">TRANSACTION DETAIL</div><h2>${esc(r.ticker)} <span class="type-badge ${r.type.toLowerCase()}">${esc(r.type)}</span></h2><p>${esc(r.company)} · ${esc(r.asset)}</p><div class="person-cell"><span class="avatar">${esc(initials(r.person))}</span><div><strong>${esc(r.person)}</strong><div class="muted">${esc(r.chamber)} · ${esc(r.party)}–${esc(r.state)}</div></div></div><div class="detail-grid"><div><small>Reported amount</small><strong>${esc(r.amount)}</strong></div><div><small>Reported owner</small><strong>${esc(r.owner)}</strong></div><div><small>Trade date</small><strong>${date(r.traded)}</strong></div><div><small>Filing date</small><strong>${date(r.filed)}</strong></div><div><small>Disclosure delay</small><strong>${lag(r)} calendar days</strong></div><div><small>Evidence</small><strong>${esc(r.quality)}</strong></div></div>${returnDetails(r)}<p>${esc(r.notes)}</p>${r.summarySource?`<p>Transcribed from <a href="${esc(r.summarySource)}" target="_blank" rel="noopener">Open Cabinet</a>. Original PDF linked below; not independently verified.</p>`:r.quality==='Secondary source'?`<p>Transcribed from <a href="${SECONDARY}" target="_blank" rel="noopener">Coldpine’s summary</a>. Rounded brackets. Original Senate record not independently verified; later amendments are not reconciled.</p>`:''}<a class="primary" target="_blank" rel="noopener" href="${esc(r.source)}">Open source filing ↗</a><p class="muted">Disclosed ranges are not execution prices. This transaction does not establish a current holding or expected return.</p>`;$('#details').showModal();}
function clear(){scope='all';page=1;$('#search').value='';$('#chamber').value='';$('#type').value='';$$('[data-scope]').forEach(b=>b.classList.toggle('selected',b.dataset.scope==='all'));renderRows()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)changeView(b.dataset.view);if(b.dataset.follow)follow(b.dataset.follow);if(b.dataset.detail)details(b.dataset.detail);if(b.dataset.cluster!==undefined)clusterDetails(b.dataset.cluster);if(b.dataset.person){clear();$('#search').value=b.dataset.person;changeView('trades');renderRows()}if(b.dataset.scope){scope=b.dataset.scope;page=1;$$('[data-scope]').forEach(x=>x.classList.toggle('selected',x===b));renderRows()}if(b.classList.contains('close'))b.closest('dialog').close()});
['search','chamber','type','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderRows()}));$('#clear').onclick=clear;$('#prev').onclick=()=>{page--;renderRows()};$('#next').onclick=()=>{page++;renderRows()};$('#bloom').onclick=()=>{clear();$('#search').value='Bloom Energy';changeView('trades');renderRows()};$('.brand').onclick=e=>{e.preventDefault();changeView('trades')};
function csv(rows){return fields.join(',')+'\r\n'+rows.map(r=>fields.map(f=>'"'+String(r[f]??'').replace(/^[=+@\t\r]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function download(name,text){const blob=new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#exportButton').onclick=()=>download('pif-disclosures.csv',csv(filtered()));
function template(){download('disclosure-template.csv',fields.join(',')+'\r\n')}
['template','dialogTemplate'].forEach(id=>$('#'+id).onclick=template);
function openImport(){$('#importStatus').textContent='Required: '+fields.filter(x=>x!=='notes').join(', ');$('#file').value='';$('#importDialog').showModal()}
['importButton','sourceImport'].forEach(id=>$('#'+id).onclick=openImport);
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('Unclosed quote in CSV.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s}
function validate(r){if(!r||fields.filter(f=>f!=='notes').some(f=>typeof r[f]!=='string'||!r[f].trim()||r[f].length>1000))throw Error('Every required field must be filled (maximum 1,000 characters).');if(!['House','Senate','Executive'].includes(r.chamber))throw Error('Office must be House, Senate or Executive.');if(!['Purchase','Sale','Exercise'].includes(r.type))throw Error('Type must be Purchase, Sale or Exercise.');if(!validDate(r.traded)||!validDate(r.filed)||r.filed<r.traded)throw Error('Use valid YYYY-MM-DD dates; filing cannot precede the trade.');if(r.filed>new Date().toISOString().slice(0,10))throw Error('Filing date cannot be in the future.');let u;try{u=new URL(r.source)}catch{throw Error('Source must be a valid HTTPS URL.')}if(u.protocol!=='https:')throw Error('Source must use HTTPS.');if(r.notes&&r.notes.length>4000)throw Error('Notes must be under 4,000 characters.')}
const key=r=>fields.map(f=>r[f]||'').join('|');
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Choose a CSV smaller than 2 MB.');const raw=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(raw.length<2)throw Error('Add at least one transaction below the header.');if(raw.length>5001)throw Error('Import at most 5,000 rows at once.');const header=raw.shift().map(x=>x.trim());if(new Set(header).size!==header.length)throw Error('Duplicate column names.');for(const f of fields.filter(f=>f!=='notes'))if(!header.includes(f))throw Error('Missing column: '+f);const seen=new Set(data.map(key)),added=[];for(let i=0;i<raw.length;i++){if(raw[i].length!==header.length)throw Error('Column count mismatch on row '+(i+2));const r=Object.fromEntries(fields.map(f=>[f,header.includes(f)?raw[i][header.indexOf(f)].trim():'']));try{validate(r)}catch(err){throw Error('Row '+(i+2)+': '+err.message)}const k=key(r);if(!seen.has(k)){seen.add(k);added.push({...r,id:crypto.randomUUID(),quality:'User-provided'})}}if(!added.length){$('#importStatus').textContent='No new rows. These transactions are already in your dataset.';return}const next=[...imported,...added];if(!persist('cl-imports',next))throw Error('Import was not saved. Enable browser storage or free up space and retry.');imported=next;data=[...SEED,...imported];render();$('#importStatus').textContent=`Imported ${added.length} transactions. Skipped ${raw.length-added.length} duplicates. Saved on this device.`;notify('Import complete')}catch(err){$('#importStatus').textContent=err.message}};
$('#clusterWindow').onchange=()=>{clusterDays=Number($('#clusterWindow').value);page=1;renderRows()};
