render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_disclosures',title:'Filter political disclosures',description:'Set the visible search and chamber filter, then return matching rows from the selected snapshot.',inputSchema:{type:'object',properties:{query:{type:'string'},chamber:{type:'string',enum:['','House','Senate','Executive']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','chamber'].includes(k))||('query'in input&&typeof input.query!=='string')||('chamber'in input&&!['','House','Senate','Executive'].includes(input.chamber)))throw Error('Invalid filter input');clear();$('#search').value=input.query||'';$('#chamber').value=input.chamber||'';changeView('trades');renderRows();return {count:filtered().length,records:filtered().slice(0,20),coverage:'Selected historical filings; not live or complete.'}}})).catch(()=>{})}catch{}}




